import numpy as np
from scipy.optimize import least_squares
eps=df['eps'].values; T=df['T'].values; s=df['sigma'].values
F={
 'eps^p':lambda p: eps**p[0],
 'exp(-p eps)':lambda p: np.exp(-p[0]*eps),
 'eps^p exp(-q eps)':lambda p: eps**p[0]*np.exp(-p[1]*eps),
 'eps^p/(1+q eps)':lambda p: eps**p[0]/(1+p[1]*eps),
 'log(1+p eps)':lambda p: np.log(1+p[0]*eps),
 'tanh(p eps)':lambda p: np.tanh(p[0]*eps),
 'eps':lambda p: eps+0*p[0],
}
G={
 'T^p':lambda p: T**p[0],
 'exp(-p T)':lambda p: np.exp(-p[0]*T),
 'exp(-p/T)':lambda p: np.exp(-p[0]/T),
 'T^p exp(-q T)':lambda p: T**p[0]*np.exp(-p[1]*T),
 'exp(p T)':lambda p: np.exp(p[0]*T),
 'T':lambda p: T+0*p[0],
}
rng=np.random.default_rng(2)
res=[]
def run(fn,gn):
    f=F[fn]; g=G[gn]
    def mdl(q):
        base=q[0]*np.tanh(q[1]*eps)+q[2]*T**q[3]*eps**1.5
        return base+q[4]*f(q[5:7])*g(q[7:9])
    bc=None
    for k in range(6):
        p0=np.r_[rng.normal(size=1),abs(rng.normal())+0.5,rng.normal(size=1),abs(rng.normal())+1,rng.normal(size=1),abs(rng.normal(size=2))+0.3,abs(rng.normal(size=2))+0.3]
        try:
            r=least_squares(lambda q: mdl(q)-s,p0,max_nfev=300)
            if np.isfinite(r.cost) and (bc is None or r.cost<bc.cost): bc=r
        except Exception: pass
    if bc is not None: res.append((bc.cost*2/np.sum((s-s.mean())**2),fn,gn,bc.x.round(3)))
for fn in F:
    for gn in G:
        run(fn,gn)
res.sort(key=lambda x:x[0])
